package com.example.billing.api;
import com.example.billing.domain.*; import java.math.BigDecimal; import java.time.*; import java.util.*;
public final class Contracts { private Contracts(){} public record ApiError(String code,String message){} public record CreateProductRequest(String name,String description,boolean active){} public record ProductResponse(UUID id,String name,String description,boolean active){public static ProductResponse from(Product x){return new ProductResponse(x.id,x.name,x.description,x.active);}} public record CreatePricePlanRequest(UUID productId,String billingType,BigDecimal amount,String currency,String billingInterval,String usageUnit){} public record PricePlanResponse(UUID id,UUID productId,String billingType,BigDecimal amount,String currency,String billingInterval,String usageUnit,boolean active){public static PricePlanResponse from(PricePlan x){return new PricePlanResponse(x.id,x.productId,x.billingType,x.amount,x.currency,x.billingInterval,x.usageUnit,x.active);}} public record CreateCustomerRequest(String email,String companyName,String billingAddress,String paymentMethodId){} public record CustomerResponse(UUID id,String email,String companyName,String billingAddress,String paymentMethodId,String status,OffsetDateTime createdAt){public static CustomerResponse from(Customer x){return new CustomerResponse(x.id,x.email,x.companyName,x.billingAddress,x.paymentMethodId,x.status,x.createdAt);}} public record CreateSubscriptionRequest(UUID customerId,UUID pricePlanId,LocalDate startDate){} public record CancelSubscriptionRequest(boolean cancelAtPeriodEnd){} public record ChangeSubscriptionPlanRequest(UUID pricePlanId){} public record SubscriptionResponse(UUID id,UUID customerId,UUID pricePlanId,String status,LocalDate startDate,LocalDate currentPeriodStart,LocalDate currentPeriodEnd,boolean cancelAtPeriodEnd){public static SubscriptionResponse from(Subscription x){return new SubscriptionResponse(x.id,x.customerId,x.pricePlanId,x.status,x.startDate,x.currentPeriodStart,x.currentPeriodEnd,x.cancelAtPeriodEnd);}} public record ProrationResult(BigDecimal unusedCredit,BigDecimal remainingPlanCost,BigDecimal amountDue){} public record ChangeSubscriptionPlanResponse(SubscriptionResponse subscription,ProrationResult proration){} public record GenerateInvoiceRequest(UUID subscriptionId){} public record InvoiceLineResponse(UUID id,String description,BigDecimal amount,BigDecimal quantity,BigDecimal unitPrice){static InvoiceLineResponse from(InvoiceLine x){return new InvoiceLineResponse(x.id,x.description,x.amount,x.quantity,x.unitPrice);}} public record InvoiceResponse(UUID id,UUID customerId,UUID subscriptionId,String status,BigDecimal amountDue,BigDecimal amountPaid,LocalDate billingPeriodStart,LocalDate billingPeriodEnd,LocalDate dueDate,OffsetDateTime createdAt,List<InvoiceLineResponse> lines){public static InvoiceResponse from(Invoice x){return new InvoiceResponse(x.id,x.customerId,x.subscriptionId,x.status,x.amountDue,x.amountPaid,x.billingPeriodStart,x.billingPeriodEnd,x.dueDate,x.createdAt,x.lines.stream().map(InvoiceLineResponse::from).toList());}} public record PayInvoiceRequest(String provider,boolean simulateFailure){} public record PaymentAttemptResponse(UUID id,int attemptNumber,String status,String failureReason,OffsetDateTime createdAt){static PaymentAttemptResponse from(PaymentAttempt x){return new PaymentAttemptResponse(x.id,x.attemptNumber,x.status,x.failureReason,x.createdAt);}} public record PaymentResponse(UUID id,UUID invoiceId,BigDecimal amount,String status,String provider,String idempotencyKey,OffsetDateTime createdAt,List<PaymentAttemptResponse> attempts){public static PaymentResponse from(Payment x){return new PaymentResponse(x.id,x.invoiceId,x.amount,x.status,x.provider,x.idempotencyKey,x.createdAt,x.attempts.stream().map(PaymentAttemptResponse::from).toList());}} public record ReportUsageRequest(UUID subscriptionId,String metricName,BigDecimal quantity,OffsetDateTime timestamp){} public record UsageRecordResponse(UUID id,UUID customerId,UUID subscriptionId,String metricName,BigDecimal quantity,OffsetDateTime timestamp,String idempotencyKey){public static UsageRecordResponse from(UsageRecord x){return new UsageRecordResponse(x.id,x.customerId,x.subscriptionId,x.metricName,x.quantity,x.timestamp,x.idempotencyKey);}} }
